PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE PROJECT_META(KEY TEXT PRIMARY KEY,VALUE TEXT);
INSERT INTO PROJECT_META VALUES('pt_separator','-');
CREATE TABLE PT(ID INTEGER PRIMARY KEY AUTOINCREMENT,NAME TEXT NOT NULL UNIQUE,PARENT INTEGER REFERENCES PT(ID),SEGMENT TEXT,DESCRIPTION TEXT,POSITION INTEGER NOT NULL DEFAULT 0,ARCHIVED INTEGER NOT NULL DEFAULT 0 CHECK(ARCHIVED IN(0,1)),CREATED_AT TEXT,UPDATED_AT TEXT);
CREATE UNIQUE INDEX IDX_PT_SIBLING_SEGMENT ON PT(IFNULL(PARENT,-1),SEGMENT);
CREATE TABLE DOC_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,TYPE TEXT NOT NULL,DESCRIPTION TEXT);
INSERT INTO DOC_TYPE VALUES(1,'SP','Specification document'),(2,'ICD','Interface Control Document');
CREATE TABLE DOCUMENT(ID INTEGER PRIMARY KEY AUTOINCREMENT,PT_ID INTEGER NOT NULL REFERENCES PT(ID),TYPE INTEGER NOT NULL REFERENCES DOC_TYPE(ID),TITLE TEXT NOT NULL UNIQUE,DESCRIPTION TEXT,TEMPLATE_PATH TEXT,METADATA_JSON TEXT);
CREATE TABLE DOCUMENT_REFERENCE(ID INTEGER PRIMARY KEY AUTOINCREMENT,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID) ON DELETE CASCADE,REFERENCE TEXT NOT NULL,IS_PRIMARY INTEGER NOT NULL DEFAULT 0 CHECK(IS_PRIMARY IN(0,1)),UNIQUE(DOC_ID,REFERENCE));
CREATE UNIQUE INDEX IDX_DOCUMENT_PRIMARY_REFERENCE ON DOCUMENT_REFERENCE(DOC_ID) WHERE IS_PRIMARY=1;
CREATE TABLE REQ_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,TYPE TEXT NOT NULL UNIQUE,CODE TEXT);
INSERT INTO REQ_TYPE(ID,TYPE) VALUES(1,'Informational'),(2,'Feature'),(3,'Use Case'),(4,'User Interface'),(5,'Non Functional'),(6,'Constraint'),(7,'System Function');
CREATE TABLE REQ_STATUS(ID INTEGER PRIMARY KEY AUTOINCREMENT,SHORTCUT TEXT NOT NULL UNIQUE,STATUS TEXT NOT NULL UNIQUE);
INSERT INTO REQ_STATUS VALUES(1,'D','Draft'),(2,'R','Review'),(3,'W','Rework'),(4,'F','Finish'),(5,'I','Implemented'),(6,'V','Valid'),(7,'N','Non Testable'),(8,'O','Obsolete');
CREATE TABLE REQ_METHOD(ID INTEGER PRIMARY KEY AUTOINCREMENT,METHOD TEXT NOT NULL);
INSERT INTO REQ_METHOD VALUES(1,'Analysis'),(2,'Test'),(3,'Review of design');
CREATE TABLE REQUIREMENT(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL,TITLE TEXT NOT NULL,DESCRIPTION TEXT,TYPE INTEGER NOT NULL REFERENCES REQ_TYPE(ID),STATUS INTEGER NOT NULL REFERENCES REQ_STATUS(ID),SOURCE TEXT,IS_TRACE_ROOT INTEGER NOT NULL DEFAULT 0 CHECK(IS_TRACE_ROOT IN(0,1)),COMMENTS TEXT,NOT_APPLICABLE INTEGER NOT NULL DEFAULT 0 CHECK(NOT_APPLICABLE IN(0,1)));
CREATE UNIQUE INDEX idx_code ON REQUIREMENT(CODE COLLATE NOCASE);
CREATE TABLE REQ_IMAGE(ID INTEGER PRIMARY KEY AUTOINCREMENT,REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,TOKEN TEXT NOT NULL UNIQUE,MIME_TYPE TEXT NOT NULL,LEGEND TEXT,IMAGE BLOB NOT NULL);
CREATE INDEX IDX_REQ_IMAGE_REQUIREMENT ON REQ_IMAGE(REQ_ID);
CREATE TABLE REQUIREMENT_PT(REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,PT_ID INTEGER NOT NULL REFERENCES PT(ID) ON DELETE CASCADE,IS_PRIMARY INTEGER NOT NULL DEFAULT 0 CHECK(IS_PRIMARY IN(0,1)),PRIMARY KEY(REQ_ID,PT_ID));
CREATE UNIQUE INDEX IDX_REQ_PT_PRIMARY ON REQUIREMENT_PT(REQ_ID) WHERE IS_PRIMARY=1;
CREATE INDEX IDX_REQUIREMENT_PT_PT ON REQUIREMENT_PT(PT_ID,REQ_ID);
CREATE TABLE REQUIREMENT_CODE_SEQUENCE(PT_ID INTEGER PRIMARY KEY REFERENCES PT(ID) ON DELETE CASCADE,NEXT_VALUE INTEGER NOT NULL DEFAULT 1 CHECK(NEXT_VALUE>0));
CREATE TABLE REQUIREMENT_RELATION_TYPE(ID INTEGER PRIMARY KEY,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL);
INSERT INTO REQUIREMENT_RELATION_TYPE VALUES(1,'DECOMPOSE','Décompose'),(2,'DERIVES_FROM','Dérive de'),(3,'DEPENDS_ON','Dépend de');
CREATE TABLE REQUIREMENT_RELATION(ID INTEGER PRIMARY KEY AUTOINCREMENT,SOURCE_REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,TARGET_REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,TYPE_ID INTEGER NOT NULL REFERENCES REQUIREMENT_RELATION_TYPE(ID),CREATED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,COMMENT TEXT,UNIQUE(SOURCE_REQ_ID,TARGET_REQ_ID,TYPE_ID),CHECK(SOURCE_REQ_ID<>TARGET_REQ_ID));
CREATE INDEX IDX_REQ_REL_SOURCE ON REQUIREMENT_RELATION(SOURCE_REQ_ID);
CREATE INDEX IDX_REQ_REL_TARGET ON REQUIREMENT_RELATION(TARGET_REQ_ID);
CREATE TABLE REQUIREMENT_VERIFICATION(ID INTEGER PRIMARY KEY AUTOINCREMENT,REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,METHOD_ID INTEGER NOT NULL REFERENCES REQ_METHOD(ID),VERIF_LEVEL TEXT,PROCEDURE_REF TEXT,REDMINE_REF TEXT,MEANS TEXT,VERDICT TEXT CHECK(VERDICT IS NULL OR VERDICT IN('C','PC','NC')),COMMENT TEXT,POSITION INTEGER NOT NULL DEFAULT 0,VERIFICATION_LEVEL_PT_ID INTEGER REFERENCES PT(ID),UNIQUE(REQ_ID,METHOD_ID));
CREATE INDEX IDX_REQ_VERIFICATION_REQ ON REQUIREMENT_VERIFICATION(REQ_ID,POSITION);
CREATE TABLE REQIF_IDENTITY(REQ_ID INTEGER PRIMARY KEY REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,EXTERNAL_ID TEXT NOT NULL UNIQUE,SOURCE_DOCUMENT TEXT,LAST_SYNC_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE REQIF_ATTRIBUTE(REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,ATTRIBUTE_ID TEXT NOT NULL,ATTRIBUTE_NAME TEXT NOT NULL,VALUE TEXT,VALUE_TYPE TEXT,PRIMARY KEY(REQ_ID,ATTRIBUTE_ID));
CREATE TABLE CONFIGURATION(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL,DESCRIPTION TEXT,ACTIVE INTEGER NOT NULL DEFAULT 1 CHECK(ACTIVE IN(0,1)),POSITION INTEGER NOT NULL DEFAULT 0,CREATED_AT TEXT,UPDATED_AT TEXT);
CREATE INDEX IDX_CONFIGURATION_ORDER ON CONFIGURATION(ACTIVE DESC,POSITION,CODE);
CREATE TABLE REQUIREMENT_APPLICABILITY(REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,CONFIG_ID INTEGER NOT NULL REFERENCES CONFIGURATION(ID) ON DELETE CASCADE,PT_ID INTEGER REFERENCES PT(ID) ON DELETE CASCADE,APPLICABLE INTEGER NOT NULL DEFAULT 1 CHECK(APPLICABLE IN(0,1)),COMMENT TEXT,PRIMARY KEY(REQ_ID,CONFIG_ID,PT_ID));
CREATE UNIQUE INDEX IDX_REQUIREMENT_CONFIG_SIMPLE ON REQUIREMENT_APPLICABILITY(REQ_ID,CONFIG_ID) WHERE PT_ID IS NULL;
CREATE INDEX IDX_APPLICABILITY_CONFIG ON REQUIREMENT_APPLICABILITY(CONFIG_ID,PT_ID,REQ_ID);
CREATE TABLE DOCUMENT_NODE(ID INTEGER PRIMARY KEY AUTOINCREMENT,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID) ON DELETE CASCADE,PARENT_ID INTEGER REFERENCES DOCUMENT_NODE(ID) ON DELETE CASCADE,NODE_TYPE TEXT NOT NULL CHECK(NODE_TYPE IN('CHAPTER','REQUIREMENT','TEXT','IMAGE')),POSITION INTEGER NOT NULL DEFAULT 0,TITLE TEXT,REQ_ID INTEGER REFERENCES REQUIREMENT(ID),TEXT_CONTENT TEXT,IMAGE_DATA BLOB,IMAGE_LEGEND TEXT,UNIQUE(DOC_ID,PARENT_ID,POSITION));
CREATE INDEX IDX_DOC_NODE_DOC ON DOCUMENT_NODE(DOC_ID,PARENT_ID,POSITION);
CREATE UNIQUE INDEX IDX_DOCUMENT_REQUIREMENT_OCCURRENCE ON DOCUMENT_NODE(DOC_ID,REQ_ID) WHERE NODE_TYPE='REQUIREMENT';
CREATE INDEX IDX_DOCUMENT_NODE_REQUIREMENT ON DOCUMENT_NODE(REQ_ID,DOC_ID);
CREATE TABLE DOCUMENT_EXPORT(ID INTEGER PRIMARY KEY AUTOINCREMENT,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID),EXPORT_KIND TEXT NOT NULL CHECK(EXPORT_KIND IN('DRAFT','PUBLICATION')),VERSION TEXT,TITLE TEXT,AUTHOR TEXT,EXPORTED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FILE_PATH TEXT,FILE_SHA256 TEXT,GED_REFERENCE TEXT,GED_LINK TEXT,SNAPSHOT_JSON TEXT,TEMPLATE_PATH TEXT,TEMPLATE_SHA256 TEXT,METADATA_JSON TEXT,DRAFT_LABEL TEXT);
CREATE INDEX IDX_DOCUMENT_EXPORT_HISTORY ON DOCUMENT_EXPORT(DOC_ID,EXPORT_KIND,EXPORTED_AT DESC);
CREATE TABLE INTERFACE(ID INTEGER PRIMARY KEY AUTOINCREMENT,ELEMENT1 INTEGER NOT NULL REFERENCES PT(ID),ELEMENT2 INTEGER NOT NULL REFERENCES PT(ID),DESCRIPTION TEXT,CODE TEXT,STATUS TEXT NOT NULL DEFAULT 'DRAFT',ARCHIVED INTEGER NOT NULL DEFAULT 0 CHECK(ARCHIVED IN(0,1)),CREATED_AT TEXT,UPDATED_AT TEXT);
CREATE INDEX IDX_INTERFACE_ENDPOINTS ON INTERFACE(ELEMENT1,ELEMENT2);
CREATE TABLE INTERFACE_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL);
INSERT INTO INTERFACE_TYPE(CODE,LABEL) VALUES('MECHANICAL','Mécanique'),('ELECTRICAL','Électrique'),('COMMUNICATION','Communication / données'),('THERMAL','Thermique'),('FLUID','Fluide'),('OTHER','Autre');
CREATE TABLE INTERFACE_TYPE_LINK(INTERFACE_ID INTEGER NOT NULL REFERENCES INTERFACE(ID) ON DELETE CASCADE,TYPE_ID INTEGER NOT NULL REFERENCES INTERFACE_TYPE(ID),PRIMARY KEY(INTERFACE_ID,TYPE_ID));
CREATE INDEX IDX_INTERFACE_TYPE_LINK_TYPE ON INTERFACE_TYPE_LINK(TYPE_ID,INTERFACE_ID);
CREATE TABLE INTERFACE_DOCUMENT(INTERFACE_ID INTEGER NOT NULL REFERENCES INTERFACE(ID) ON DELETE CASCADE,DOC_ID INTEGER NOT NULL REFERENCES DOCUMENT(ID) ON DELETE CASCADE,CHAPTER_NODE_ID INTEGER REFERENCES DOCUMENT_NODE(ID),PRIMARY KEY(INTERFACE_ID,DOC_ID));
CREATE INDEX IDX_INTERFACE_DOCUMENT_DOCUMENT ON INTERFACE_DOCUMENT(DOC_ID,INTERFACE_ID);
CREATE TABLE INTERFACE_REQUIREMENT(INTERFACE_ID INTEGER NOT NULL REFERENCES INTERFACE(ID) ON DELETE CASCADE,REQ_ID INTEGER NOT NULL REFERENCES REQUIREMENT(ID) ON DELETE CASCADE,PRIMARY KEY(INTERFACE_ID,REQ_ID));
CREATE INDEX IDX_INTERFACE_REQUIREMENT_REQ ON INTERFACE_REQUIREMENT(REQ_ID);
CREATE TABLE CHANGE_TYPE(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL,ACTIVE INTEGER NOT NULL DEFAULT 1 CHECK(ACTIVE IN(0,1)));
INSERT INTO CHANGE_TYPE(CODE,LABEL) VALUES('CHANGE_REQUEST','Demande de changement'),('WAIVER','Waiver / Dérogation'),('DEVIATION','Déviation'),('OTHER','Autre');
CREATE TABLE CHANGE_STATUS(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,LABEL TEXT NOT NULL,IS_FINAL INTEGER NOT NULL DEFAULT 0 CHECK(IS_FINAL IN(0,1)),POSITION INTEGER NOT NULL DEFAULT 0);
INSERT INTO CHANGE_STATUS(CODE,LABEL,IS_FINAL,POSITION) VALUES('OPEN','Ouvert',0,10),('IN_REVIEW','En instruction',0,20),('APPROVED','Approuvé',1,30),('REJECTED','Rejeté',1,40),('CLOSED','Clos',1,50);
CREATE TABLE CHANGE_ITEM(ID INTEGER PRIMARY KEY AUTOINCREMENT,CODE TEXT NOT NULL UNIQUE,TYPE_ID INTEGER NOT NULL REFERENCES CHANGE_TYPE(ID),STATUS_ID INTEGER NOT NULL REFERENCES CHANGE_STATUS(ID),DESCRIPTION TEXT,DECISION TEXT,OPENED_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CLOSED_AT TEXT,EXTERNAL_REFERENCE TEXT,EXTERNAL_LINK TEXT,ARCHIVED INTEGER NOT NULL DEFAULT 0 CHECK(ARCHIVED IN(0,1)),UPDATED_AT TEXT);
CREATE INDEX IDX_CHANGE_STATUS ON CHANGE_ITEM(ARCHIVED,STATUS_ID,TYPE_ID);
CREATE TABLE CHANGE_LINK(ID INTEGER PRIMARY KEY AUTOINCREMENT,CHANGE_ID INTEGER NOT NULL REFERENCES CHANGE_ITEM(ID) ON DELETE CASCADE,OBJECT_TYPE TEXT NOT NULL CHECK(OBJECT_TYPE IN('REQUIREMENT','PT','CONFIGURATION','INTERFACE','DOCUMENT')),OBJECT_ID INTEGER NOT NULL,UNIQUE(CHANGE_ID,OBJECT_TYPE,OBJECT_ID));
CREATE INDEX IDX_CHANGE_LINK_OBJECT ON CHANGE_LINK(OBJECT_TYPE,OBJECT_ID);
CREATE TABLE EVENT_LOG(ID INTEGER PRIMARY KEY AUTOINCREMENT,EVENT_TIME TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,AUTHOR TEXT,EVENT_TYPE TEXT NOT NULL,OBJECT_TYPE TEXT NOT NULL,OBJECT_ID INTEGER,BEFORE_JSON TEXT,AFTER_JSON TEXT,COMMENT TEXT,EVENT_GROUP TEXT,PAYLOAD_VERSION INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IDX_EVENT_OBJECT ON EVENT_LOG(OBJECT_TYPE,OBJECT_ID,EVENT_TIME);
CREATE INDEX IDX_EVENT_GROUP ON EVENT_LOG(EVENT_GROUP);
CREATE TABLE EVENT_SUBJECT(EVENT_ID INTEGER NOT NULL REFERENCES EVENT_LOG(ID) ON DELETE CASCADE,OBJECT_TYPE TEXT NOT NULL,OBJECT_ID INTEGER NOT NULL,ROLE TEXT NOT NULL DEFAULT 'AFFECTED',PRIMARY KEY(EVENT_ID,OBJECT_TYPE,OBJECT_ID));
CREATE INDEX IDX_EVENT_SUBJECT_OBJECT ON EVENT_SUBJECT(OBJECT_TYPE,OBJECT_ID,EVENT_ID);
CREATE TABLE EVENT_CONTEXT(ID INTEGER PRIMARY KEY CHECK(ID=1),AUTHOR TEXT NOT NULL DEFAULT 'Utilisateur',EVENT_GROUP TEXT);
INSERT INTO EVENT_CONTEXT(ID,AUTHOR) VALUES(1,'Utilisateur');
CREATE TABLE MIGRATION_REPORT(ID INTEGER PRIMARY KEY AUTOINCREMENT,RUN_AT TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FROM_VERSION INTEGER NOT NULL,TO_VERSION INTEGER NOT NULL,REPORT TEXT NOT NULL);
CREATE TRIGGER REQUIREMENT_DELETE_GUARD BEFORE DELETE ON REQUIREMENT BEGIN SELECT RAISE(ABORT,'Une exigence tracée doit être rendue obsolète, pas supprimée.'); END;
CREATE TRIGGER REQUIREMENT_RELATION_CYCLE BEFORE INSERT ON REQUIREMENT_RELATION WHEN NEW.TYPE_ID=1 AND EXISTS(WITH RECURSIVE D(ID) AS (SELECT TARGET_REQ_ID FROM REQUIREMENT_RELATION WHERE SOURCE_REQ_ID=NEW.TARGET_REQ_ID AND TYPE_ID=1 UNION SELECT X.TARGET_REQ_ID FROM REQUIREMENT_RELATION X JOIN D ON X.SOURCE_REQ_ID=D.ID WHERE X.TYPE_ID=1) SELECT 1 FROM D WHERE ID=NEW.SOURCE_REQ_ID) BEGIN SELECT RAISE(ABORT,'Cycle de décomposition interdit.'); END;
CREATE TRIGGER DOCUMENT_NODE_PARENT_INSERT BEFORE INSERT ON DOCUMENT_NODE WHEN NEW.PARENT_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM DOCUMENT_NODE P WHERE P.ID=NEW.PARENT_ID AND P.DOC_ID=NEW.DOC_ID AND P.NODE_TYPE='CHAPTER') BEGIN SELECT RAISE(ABORT,'Parent de document invalide'); END;
CREATE TRIGGER DOCUMENT_NODE_PARENT_UPDATE BEFORE UPDATE OF PARENT_ID,DOC_ID ON DOCUMENT_NODE WHEN NEW.PARENT_ID IS NOT NULL AND NOT EXISTS(SELECT 1 FROM DOCUMENT_NODE P WHERE P.ID=NEW.PARENT_ID AND P.DOC_ID=NEW.DOC_ID AND P.NODE_TYPE='CHAPTER') BEGIN SELECT RAISE(ABORT,'Parent de document invalide'); END;
CREATE TRIGGER DOCUMENT_NODE_CYCLE_UPDATE BEFORE UPDATE OF PARENT_ID ON DOCUMENT_NODE WHEN NEW.PARENT_ID IS NOT NULL AND EXISTS(WITH RECURSIVE D(ID) AS (SELECT ID FROM DOCUMENT_NODE WHERE PARENT_ID=NEW.ID UNION ALL SELECT N.ID FROM DOCUMENT_NODE N JOIN D ON N.PARENT_ID=D.ID) SELECT 1 FROM D WHERE ID=NEW.PARENT_ID) BEGIN SELECT RAISE(ABORT,'Cycle de document interdit'); END;
CREATE TRIGGER CHANGE_PT_DELETE_GUARD BEFORE DELETE ON PT WHEN EXISTS(SELECT 1 FROM CHANGE_LINK WHERE OBJECT_TYPE='PT' AND OBJECT_ID=OLD.ID) BEGIN SELECT RAISE(ABORT,'Objet lié à un changement : archivez-le ou retirez d''abord l''association.'); END;
CREATE TRIGGER CHANGE_CONFIGURATION_DELETE_GUARD BEFORE DELETE ON CONFIGURATION WHEN EXISTS(SELECT 1 FROM CHANGE_LINK WHERE OBJECT_TYPE='CONFIGURATION' AND OBJECT_ID=OLD.ID) BEGIN SELECT RAISE(ABORT,'Objet lié à un changement : archivez-le ou retirez d''abord l''association.'); END;
CREATE TRIGGER CHANGE_INTERFACE_DELETE_GUARD BEFORE DELETE ON INTERFACE WHEN EXISTS(SELECT 1 FROM CHANGE_LINK WHERE OBJECT_TYPE='INTERFACE' AND OBJECT_ID=OLD.ID) BEGIN SELECT RAISE(ABORT,'Objet lié à un changement : archivez-le ou retirez d''abord l''association.'); END;
CREATE TRIGGER CHANGE_DOCUMENT_DELETE_GUARD BEFORE DELETE ON DOCUMENT WHEN EXISTS(SELECT 1 FROM CHANGE_LINK WHERE OBJECT_TYPE='DOCUMENT' AND OBJECT_ID=OLD.ID) BEGIN SELECT RAISE(ABORT,'Objet lié à un changement : archivez-le ou retirez d''abord l''association.'); END;
CREATE TRIGGER DOCUMENT_PUBLICATION_IMMUTABLE BEFORE UPDATE ON DOCUMENT_EXPORT WHEN OLD.EXPORT_KIND='PUBLICATION' AND (NEW.DOC_ID<>OLD.DOC_ID OR NEW.EXPORT_KIND<>OLD.EXPORT_KIND OR IFNULL(NEW.VERSION,'')<>IFNULL(OLD.VERSION,'') OR IFNULL(NEW.TITLE,'')<>IFNULL(OLD.TITLE,'') OR IFNULL(NEW.AUTHOR,'')<>IFNULL(OLD.AUTHOR,'') OR NEW.EXPORTED_AT<>OLD.EXPORTED_AT OR IFNULL(NEW.FILE_PATH,'')<>IFNULL(OLD.FILE_PATH,'') OR IFNULL(NEW.FILE_SHA256,'')<>IFNULL(OLD.FILE_SHA256,'') OR IFNULL(NEW.SNAPSHOT_JSON,'')<>IFNULL(OLD.SNAPSHOT_JSON,'') OR IFNULL(NEW.TEMPLATE_PATH,'')<>IFNULL(OLD.TEMPLATE_PATH,'') OR IFNULL(NEW.TEMPLATE_SHA256,'')<>IFNULL(OLD.TEMPLATE_SHA256,'') OR IFNULL(NEW.METADATA_JSON,'')<>IFNULL(OLD.METADATA_JSON,'')) BEGIN SELECT RAISE(ABORT,'Une publication est immuable'); END;
CREATE TRIGGER DOCUMENT_PUBLICATION_NODELETE BEFORE DELETE ON DOCUMENT_EXPORT WHEN OLD.EXPORT_KIND='PUBLICATION' BEGIN SELECT RAISE(ABORT,'Une publication est immuable'); END;
CREATE TRIGGER AUDIT_EVENT_CONTEXT AFTER INSERT ON EVENT_LOG WHEN NEW.AUTHOR IS NULL OR NEW.AUTHOR='' BEGIN UPDATE EVENT_LOG SET AUTHOR=(SELECT AUTHOR FROM EVENT_CONTEXT WHERE ID=1),EVENT_GROUP=COALESCE(NEW.EVENT_GROUP,(SELECT EVENT_GROUP FROM EVENT_CONTEXT WHERE ID=1)) WHERE ID=NEW.ID; END;
CREATE TRIGGER AUDIT_DOCUMENT_INSERT AFTER INSERT ON DOCUMENT BEGIN INSERT INTO EVENT_LOG(AUTHOR,EVENT_GROUP,EVENT_TYPE,OBJECT_TYPE,OBJECT_ID,AFTER_JSON) SELECT AUTHOR,EVENT_GROUP,'CREATE','DOCUMENT',NEW.ID,json_object('title',NEW.TITLE,'description',NEW.DESCRIPTION) FROM EVENT_CONTEXT WHERE ID=1; END;
CREATE TRIGGER AUDIT_DOCUMENT_UPDATE AFTER UPDATE ON DOCUMENT BEGIN INSERT INTO EVENT_LOG(AUTHOR,EVENT_GROUP,EVENT_TYPE,OBJECT_TYPE,OBJECT_ID,BEFORE_JSON,AFTER_JSON) SELECT AUTHOR,EVENT_GROUP,'UPDATE','DOCUMENT',NEW.ID,json_object('title',OLD.TITLE,'description',OLD.DESCRIPTION),json_object('title',NEW.TITLE,'description',NEW.DESCRIPTION) FROM EVENT_CONTEXT WHERE ID=1; END;
CREATE TRIGGER AUDIT_DOCUMENT_DELETE AFTER DELETE ON DOCUMENT BEGIN INSERT INTO EVENT_LOG(AUTHOR,EVENT_GROUP,EVENT_TYPE,OBJECT_TYPE,OBJECT_ID,BEFORE_JSON) SELECT AUTHOR,EVENT_GROUP,'DELETE','DOCUMENT',OLD.ID,json_object('title',OLD.TITLE,'description',OLD.DESCRIPTION) FROM EVENT_CONTEXT WHERE ID=1; END;
CREATE TRIGGER AUDIT_GED_UPDATE AFTER UPDATE OF GED_REFERENCE,GED_LINK ON DOCUMENT_EXPORT WHEN NEW.GED_REFERENCE IS NOT OLD.GED_REFERENCE OR NEW.GED_LINK IS NOT OLD.GED_LINK BEGIN INSERT INTO EVENT_LOG(AUTHOR,EVENT_GROUP,EVENT_TYPE,OBJECT_TYPE,OBJECT_ID,BEFORE_JSON,AFTER_JSON) SELECT AUTHOR,EVENT_GROUP,'GED_ASSOCIATION','DOCUMENT',NEW.DOC_ID,json_object('reference',OLD.GED_REFERENCE,'link',OLD.GED_LINK),json_object('reference',NEW.GED_REFERENCE,'link',NEW.GED_LINK) FROM EVENT_CONTEXT WHERE ID=1; END;
CREATE TRIGGER CONFIGURATION_NEW AFTER INSERT ON CONFIGURATION BEGIN INSERT INTO EVENT_LOG(EVENT_TYPE,OBJECT_TYPE,OBJECT_ID,AFTER_JSON) VALUES('CREATE','CONFIGURATION',NEW.ID,json_object('code',NEW.CODE,'label',NEW.LABEL,'active',NEW.ACTIVE,'position',NEW.POSITION)); END;
CREATE TRIGGER CONFIGURATION_UPDATE AFTER UPDATE ON CONFIGURATION BEGIN UPDATE CONFIGURATION SET UPDATED_AT=CURRENT_TIMESTAMP WHERE ID=NEW.ID AND UPDATED_AT IS OLD.UPDATED_AT; INSERT INTO EVENT_LOG(EVENT_TYPE,OBJECT_TYPE,OBJECT_ID,BEFORE_JSON,AFTER_JSON) VALUES(CASE WHEN OLD.ACTIVE<>NEW.ACTIVE THEN CASE NEW.ACTIVE WHEN 1 THEN 'RESTORE' ELSE 'ARCHIVE' END ELSE 'UPDATE' END,'CONFIGURATION',NEW.ID,json_object('code',OLD.CODE,'label',OLD.LABEL,'description',OLD.DESCRIPTION,'active',OLD.ACTIVE,'position',OLD.POSITION),json_object('code',NEW.CODE,'label',NEW.LABEL,'description',NEW.DESCRIPTION,'active',NEW.ACTIVE,'position',NEW.POSITION)); END;
CREATE TRIGGER DOCUMENT_EXPORT_LOG AFTER INSERT ON DOCUMENT_EXPORT BEGIN INSERT INTO EVENT_LOG(EVENT_TYPE,OBJECT_TYPE,OBJECT_ID,AFTER_JSON) VALUES(CASE NEW.EXPORT_KIND WHEN 'DRAFT' THEN 'EXPORT_DRAFT' ELSE 'PUBLISH' END,'DOCUMENT',NEW.DOC_ID,json_object('export_id',NEW.ID,'version',NEW.VERSION,'path',NEW.FILE_PATH,'sha256',NEW.FILE_SHA256)); END;
CREATE TRIGGER AUDIT_EVENT_SUBJECT AFTER INSERT ON EVENT_LOG WHEN NEW.OBJECT_ID IS NOT NULL BEGIN INSERT OR IGNORE INTO EVENT_SUBJECT(EVENT_ID,OBJECT_TYPE,OBJECT_ID,ROLE) VALUES(NEW.ID,NEW.OBJECT_TYPE,NEW.OBJECT_ID,'PRIMARY'); END;
PRAGMA user_version=21;
COMMIT;
PRAGMA foreign_keys=ON;
